 for(let i=0;i<calls.length;i++){const c=calls[i],s=c.response.content.filter(x=>x.type==="text").map(x=>x.text).join("\n");if(c.type==="play"){actual("X",c.move);const m=s.match(/Your opponent played ([A-HJ][1-9]|pass)\./);if(m)actual("O",m[1]);else if(/Your opponent passed\./.test(s))actual("O","pass");else throw Error("reply not parsed");}const rows={};for(const l of s.split("\n")){const m=l.match(/^\s*([1-9])\s+([XO.](?:\s+[XO.]){8})\s+[1-9]\s*$/);if(m)m[2].split(/\s+/).forEach((v,j)=>rows[cols[j]+m[1]]=v);}const boardMatch=Object.keys(rows).length===81&&Object.keys(b).every(p=>b[p]===rows[p]);const m=s.match(/Captured by Black: (\d+); by White: (\d+)/),capturesMatch=!!m&&cap.X===+m[1]&&cap.O===+m[2];const km=s.match(/Ko point: (none|[A-HJ][1-9])/),koMatch=!!km&&(km[1]==="none"?null:km[1])===ko;checks.push({call:i,throughMove:history.length,boardMatch,capturesMatch,koMatch});if(!boardMatch||!capturesMatch||!koMatch)throw Error("replay mismatch "+i);}
